// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

import org.junit.jupiter.api.Test;

class LmdbFactorizedBatchTest {

	@Test
	void sipAndRelocatedFilterAvoidFlatteningAndPreserveRoots() {
		LmdbFactorizedBatch batch = new LmdbFactorizedBatch(128, 2);
		for (int i = 0; i < 128; i++) {
			batch.addRoot(i + 1);
		}
		batch.expand(new SyntheticRun(16, 1000), false);
		long[] domainValues = new long[128 * 2];
		int at = 0;
		for (int root = 1; root <= 128; root++) {
			domainValues[at++] = root * 1000L;
			domainValues[at++] = root * 1000L + 8;
		}
		LmdbNativeSipFilter.Domain domain = LmdbNativeSipFilter.sorted(domainValues, 0, at, true);
		assertEquals(256, batch.applySip(0, domain));
		batch.expand(new SyntheticRun(8, 100), false);
		assertEquals(2048, batch.level(1).valueCount());
		assertEquals(256, batch.filter(1, value -> value % 800 == 0, false));
		assertEquals(128, batch.countDistinctRoots());
		assertEquals(256, batch.sumLeafMultiplicity());
	}

	@Test
	void optionalUsesValidityInsteadOfCopyingAncestorColumns() {
		LmdbFactorizedBatch batch = new LmdbFactorizedBatch(2, 1);
		batch.addRoot(1);
		batch.addRoot(2);
		LmdbFactorizedBatch.Level level = batch.expand(new LmdbFactorizedBatch.RunReader() {
			@Override
			public int bindSize(long key) {
				return key == 1 ? 0 : 1;
			}

			@Override
			public long neighborAt(int ordinal) {
				return 22;
			}
		}, true);
		assertEquals(2, level.valueCount());
		assertFalse(level.validAt(0));
		assertEquals(22, level.valueAt(1));
	}

	private static final class SyntheticRun implements LmdbFactorizedBatch.RunReader {
		private final int size;
		private final int scale;
		private long key;

		SyntheticRun(int size, int scale) {
			this.size = size;
			this.scale = scale;
		}

		@Override
		public int bindSize(long key) {
			this.key = key;
			return size;
		}

		@Override
		public long neighborAt(int ordinal) {
			return key * scale + ordinal;
		}
	}
}
